  [40911] = "{id=40911,BuffName='提尔锋',BuffRate={Odds=100},BuffEffect={Itemid=40348,SkillID=1001001,type='GetSkill'},Dsc='提尔的力量将治愈范围内所有的疾病及异常状态，为所有人带来健康。使范围8米内的所有友方获得【提尔祝福】效果。【提尔祝福】：瞬间恢复25%MaxHp，解除所有异常状态（包括万能无法解除的异常状态）并免疫异常状态，持续5秒，CD：180秒。',}",
  [40920] = "{id=40920,BuffName='提尔锋3[1]',BuffRate={Odds=100},BuffEffect={Agi=30,AngelDamPer=0.5,AtkPer=0.24,BruteDamPer=0.5,DamIncrease=0.18,DamReduc=0.1,DeadLessDamPer=0.5,DemiHumanDamPer=0.5,DemonDamPer=0.5,Dex=30,DragonDamPer=0.5,FishDamPer=0.5,FormlessDamPer=0.5,Hit=50,InsectDamPer=0.5,Int=20,Luk=20,MDamReduc=0.1,MaxHp=35000,PlantDamPer=0.5,Str=30,Vit=20,type='AttrChange'},Dsc='力量＋10\n敏捷＋10\n灵巧＋10\n全能力＋20\n命中＋50\n物理攻击＋24%\n物理伤害＋18%\n对全种族伤害＋50%\n生命上限＋35000\n物伤减免＋10%，魔伤减免＋10%',}",
  [40921] = "{id=40921,BuffName='提尔锋',BuffRate={Odds=100},BuffEffect={Itemid=40349,SkillID=1001002,type='GetSkill'},Dsc='提尔的力量将治愈范围内所有的疾病及异常状态，为所有人带来健康。使范围8米内的所有友方获得【提尔祝福】效果。【提尔祝福】：瞬间恢复45%MaxHp，解除所有异常状态（包括万能无法解除的异常状态）并免疫异常状态，持续5秒，CD：120秒',}",
