  [40940] = "{id=40940,BuffName='银槲之剑2[1]',BuffRate={Odds=100},BuffEffect={Agi=14,AngelDamPer=0.4,AtkPer=0.36,BruteDamPer=0.4,DamReduc=0.05,DeadLessDamPer=0.4,DemiHumanDamPer=0.4,DemonDamPer=0.4,Dex=14,DragonDamPer=0.4,FishDamPer=0.4,FormlessDamPer=0.4,Hit=50,InsectDamPer=0.4,Int=14,Luk=14,MDamReduc=0.05,MaxHp=23500,PlantDamPer=0.4,Str=32,Vit=26,type='AttrChange'},Dsc='力量＋18\n体质＋12\n全能力＋14\n命中＋50\n物理攻击＋36%\n对全种族伤害＋40%\n生命上限＋23500\n物伤减免＋5%，魔伤减免＋5%',}",
  [40941] = "{id=40941,BuffName='银槲之剑',BuffRate={Odds=100},BuffEffect={Itemid=40753,SkillID=1000001,type='GetSkill'},Dsc='银槲之剑施放虚无力量可能让使用者在【虚无空间】内进行短距离瞬移。【虚无空间】：玩家可以瞬间移动至6米范围内任何位置，银槲之剑的力量将可以使玩家在第一次使用后的6秒内使用第二次虚无空间（使用后1秒内不能连续使用）。不过虚无空间的力量过于强大，每次使用后都会在原位置残存虚无空间的能量。残存的能量能被所有人察觉。每次使用【虚无空间】后都会将玩家进入【虚空隐匿】状态，【虚空隐匿】会让使用者进入隐匿，持续5秒。【虚空隐匿】状态下首次攻击提升30%伤害，CD：90秒。',}",
  [40950] = "{id=40950,BuffName='银槲之剑3[1]',BuffRate={Odds=100},BuffEffect={Agi=20,AngelDamPer=0.5,AtkPer=0.48,BruteDamPer=0.5,DamReduc=0.1,DeadLessDamPer=0.5,DemiHumanDamPer=0.5,DemonDamPer=0.5,Dex=20,DragonDamPer=0.5,FishDamPer=0.5,FormlessDamPer=0.5,Hit=50,InsectDamPer=0.5,Int=20,Luk=20,MDamReduc=0.1,MaxHp=32000,PlantDamPer=0.5,Str=38,Vit=32,type='AttrChange'},Dsc='力量＋18\n体质＋12\n全能力＋20\n命中＋50\n物理攻击＋48%\n对全种族伤害＋50%\n生命上限＋32000\n物伤减免＋10%，魔伤减免＋10%',}",
  [40951] = "{id=40951,BuffName='银槲之剑',BuffRate={Odds=100},BuffEffect={Itemid=40754,SkillID=1000002,type='GetSkill'},Dsc='银槲之剑施放虚无力量可能让使用者在【虚无空间】内进行短距离瞬移。【虚无空间】：玩家可以瞬间移动至6米范围内任何位置，银槲之剑的力量将可以使玩家在第一次使用后的6秒内使用第二次虚无空间（使用后1秒内不能连续使用）。不过虚无空间的力量过于强大，每次使用后都会在原位置残存虚无空间的能量。残存的能量能被所有人察觉。每次使用【虚无空间】后都会将玩家进入【虚空隐匿】状态，【虚空隐匿】会让使用者进入隐匿，持续5秒。【虚空隐匿】状态下首次攻击提升60%伤害，CD：60秒。',}",
