  [47200] = "{id=47200,BuffName='雷神之锤4[1]',BuffRate={Odds=100},BuffEffect={Agi=20,AngelDamPer=0.6,BruteDamPer=0.6,DamReduc=0.15,DamSpike=0.36,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=20,DragonDamPer=0.6,FishDamPer=0.6,FormlessDamPer=0.6,Hit=50,InsectDamPer=0.6,Int=30,Luk=20,MDamReduc=0.15,MaxHp=40000,PlantDamPer=0.6,Str=30,Vit=30,type='AttrChange'},Dsc='力量＋10\n智力＋10\n体质＋10\n全能力＋20\n命中＋50\n物理穿刺＋36%\n对全种族伤害＋60%\n生命上限＋40000\n物伤减免＋15%，魔伤减免＋15%',}",
  [47201] = "{id=47201,BuffName='雷神之锤',BuffRate={Odds=100},BuffEffect={Itemid=41596,SkillID=1005002,type='GetSkill'},Dsc='雷神之锤充满了雷神的雷电力量，在每次普通攻击敌人时都将施放【雷神之怒】。【雷神之怒】：对目标造成额外（自身物理攻击＋魔法攻击）*100%的真实伤害，并对目标周围5米范围内最多5名敌对目标造成自身攻击100%的伤害。每个被【雷神之怒】及溅射伤害影响的目标都有20%的概率减速30%，持续2秒',}",
  [47210] = "{id=47210,BuffName='万神的注视4[1]',BuffRate={Odds=100},BuffEffect={Agi=20,AngelDamPer=0.6,BruteDamPer=0.6,CTChangePer=-0.05,DamReduc=0.15,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=30,DragonDamPer=0.6,FishDamPer=0.6,FormlessDamPer=0.6,InsectDamPer=0.6,Int=40,Luk=20,MAtkPer=0.64,MDamReduc=0.15,MaxHp=34500,PlantDamPer=0.6,RangeDam=0.15,Str=20,Vit=20,type='AttrChange'},Dsc='智力＋20\n灵巧＋10\n全能力＋20\n提升15%法师系范围型技能伤害\n可变吟唱时间－5%\n魔法攻击＋64%\n对全种族伤害＋60%\n生命上限＋34500\n物伤减免＋15%，魔伤减免＋15%',}",
  [47211] = "{id=47211,BuffName='万神的注视',BuffRate={Odds=100},BuffEffect={Itemid=40696,SkillID=1006002,type='GetSkill'},Dsc='万神赐予众生无比的智慧及爱护，使范围8米内的所有友方获得【万神的眷顾】效果。【万神的眷顾】：所有吟唱不会被打断，所有技能可变吟唱缩减100%，所有技能固定吟唱时间减少100%，持续8秒，CD：90秒',}",
  [47220] = "{id=47220,BuffName='金枝4[1]',BuffRate={Odds=100},BuffEffect={Agi=20,AngelDamPer=0.6,BruteDamPer=0.6,DamReduc=0.15,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=20,DragonDamPer=0.6,FishDamPer=0.6,FormlessDamPer=0.6,HealEncPer=0.15,IgnoreMDef=0.35,InsectDamPer=0.6,Int=38,Luk=20,MAtkPer=0.4,MDamReduc=0.15,MaxHp=36000,PlantDamPer=0.6,SpCostPer=-0.1,Str=20,Vit=32,type='AttrChange'},Dsc='智力＋18\n体质＋12\n全能力＋20\n治疗加成＋15%\n所有技能SP消耗－10%\n魔法攻击＋40%\n忽视魔法防御＋35%\n对全种族伤害＋60%\n生命上限＋36000\n物伤减免＋15%，魔伤减免＋15%',}",
  [47221] = "{id=47221,BuffName='金枝',BuffRate={Odds=100},BuffEffect={Itemid=40697,SkillID=1007002,type='GetSkill'},Dsc='金枝中散发出天地树之力量，使16米范围内所有阵亡的友方目标全部复活，并恢复被复活目标100%MaxHp。该效果不受GVG中复活时间限制。CD：135秒',}",
  [47230] = "{id=47230,BuffName='万物安息4[1]',BuffRate={Odds=100},BuffEffect={Agi=20,AngelDamPer=0.6,BruteDamPer=0.6,Cri=35,CriDamPer=0.24,DamReduc=0.15,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=20,DragonDamPer=0.6,FishDamPer=0.6,FormlessDamPer=0.6,InsectDamPer=0.6,Int=20,Luk=30,MDamReduc=0.15,MaxHp=37500,PlantDamPer=0.6,Str=40,Vit=20,type='AttrChange'},Dsc='力量＋20\n幸运＋10\n全能力＋20\n暴击＋35\n暴击伤害＋24%\n对全种族伤害＋60%\n生命上限＋37500\n物伤减免＋15%，魔伤减免＋15%',}",
  [47231] = "{id=47231,BuffName='万物安息',BuffRate={Odds=100},BuffEffect={Itemid=40971,SkillID=1008002,type='GetSkill'},Dsc='万物安息拥有无声无息暗杀的特殊能力，使用万物安息的暗杀者们总是能够神不知鬼不觉的完成暗杀任务。万物安息可以使5米范围内所有友方都获得【幻境保护】效果。【幻境保护】：进入隐匿的状态，无法被直接看到，持续15秒，CD：135秒。【幻境保护】状态下不会被范围技能攻击而解除状态，但是伤害及异常状态依然可以击中【幻境保护】状态下的玩家。攻击目标后隐身状态解除',}",
  [47240] = "{id=47240,BuffName='提尔锋4[1]',BuffRate={Odds=100},BuffEffect={Agi=30,AngelDamPer=0.6,AtkPer=0.28,BruteDamPer=0.6,DamIncrease=0.21,DamReduc=0.15,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=30,DragonDamPer=0.6,FishDamPer=0.6,FormlessDamPer=0.6,Hit=50,InsectDamPer=0.6,Int=20,Luk=20,MDamReduc=0.15,MaxHp=43500,PlantDamPer=0.6,Str=30,Vit=20,type='AttrChange'},Dsc='力量＋10\n敏捷＋10\n灵巧＋10\n全能力＋20\n命中＋50\n物理攻击＋28%\n物理伤害＋21%\n对全种族伤害＋60%\n生命上限＋43500\n物伤减免＋15%，魔伤减免＋15%',}",
  [47241] = "{id=47241,BuffName='提尔锋',BuffRate={Odds=100},BuffEffect={Itemid=40400,SkillID=1001002,type='GetSkill'},Dsc='提尔的力量将治愈范围内所有的疾病及异常状态，为所有人带来健康。使范围8米内的所有友方获得【提尔祝福】效果。【提尔祝福】：瞬间恢复45%MaxHp，解除所有异常状态（包括万能无法解除的异常状态）并免疫异常状态，持续5秒，CD：120秒',}",
  [47250] = "{id=47250,BuffName='银槲之剑4[1]',BuffRate={Odds=100},BuffEffect={Agi=20,AngelDamPer=0.6,AtkPer=0.5,BruteDamPer=0.6,DamReduc=0.15,DamSpike=0.08,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=20,DragonDamPer=0.6,FishDamPer=0.6,FormlessDamPer=0.6,Hit=50,InsectDamPer=0.6,Int=20,Luk=20,MDamReduc=0.15,MaxHp=40000,PlantDamPer=0.6,Str=38,Vit=32,type='AttrChange'},Dsc='力量＋18\n体质＋12\n全能力＋20\n命中＋50\n物理攻击＋50%\n物理穿刺＋8%\n对全种族伤害＋60%\n生命上限＋40000\n物伤减免＋15%，魔伤减免＋15%',}",
  [47251] = "{id=47251,BuffName='银槲之剑',BuffRate={Odds=100},BuffEffect={Itemid=40796,SkillID=1000002,type='GetSkill'},Dsc='银槲之剑施放虚无力量可能让使用者在【虚无空间】内进行短距离瞬移。【虚无空间】：玩家可以瞬间移动至6米范围内任何位置，银槲之剑的力量将可以使玩家在第一次使用后的6秒内使用第二次虚无空间（使用后1秒内不能连续使用）。不过虚无空间的力量过于强大，每次使用后都会在原位置残存虚无空间的能量。残存的能量能被所有人察觉。每次使用【虚无空间】后都会将玩家进入【虚空隐匿】状态，【虚空隐匿】会让使用者进入隐匿，持续5秒。【虚空隐匿】状态下首次攻击提升60%伤害，CD：60秒。',}",
  [47260] = "{id=47260,BuffName='永恒之枪4[1]',BuffRate={Odds=100},BuffEffect={Agi=32,AngelDamPer=0.6,BruteDamPer=0.6,DamIncrease=0.24,DamReduc=0.15,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=20,DragonDamPer=0.6,EquipASPD=0.1,FishDamPer=0.6,FormlessDamPer=0.6,IgnoreDef=0.35,InsectDamPer=0.6,Int=20,Luk=20,MDamReduc=0.15,MaxHp=41500,PlantDamPer=0.6,Str=38,Vit=20,type='AttrChange'},Dsc='力量＋18\n敏捷＋12\n全能力＋20\n装备攻速＋10%\n物理伤害＋24%\n忽视物理防御＋35%\n对全种族伤害＋60%\n生命上限＋41500\n物伤减免＋15%，魔伤减免＋15%',}",
  [47261] = "{id=47261,BuffName='永恒之枪',BuffRate={Odds=100},BuffEffect={Itemid=40086,SkillID=1003002,type='GetSkill'},Dsc='从永恒之枪中迸发出【女武神的意志】照耀6米范围内所有的敌方目标。【女武神的意志】：受到女武神的意志影响无法施放技能。该效果不能被万能药解除（沉默），持续6秒，CD：90秒',}",
  [47270] = "{id=47270,BuffName='湮灭者4[1]',BuffRate={Odds=100},BuffEffect={Agi=20,AngelDamPer=0.6,BruteDamPer=0.6,DamReduc=0.15,DamSpike=0.35,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=30,DragonDamPer=0.6,FishDamPer=0.6,FormlessDamPer=0.6,IgnoreDef=0.45,InsectDamPer=0.6,Int=20,Luk=20,MDamReduc=0.15,MaxHp=43500,MaxSp=500,PlantDamPer=0.6,Str=40,Vit=20,type='AttrChange'},Dsc='力量＋20\n灵巧＋10\n全能力＋20\n魔法上限＋500\n物理穿刺＋35%\n忽视物理防御＋45%\n对全种族伤害＋60%\n生命上限＋43500\n物伤减免＋15%，魔伤减免＋15%',}",
  [47271] = "{id=47271,BuffName='湮灭者',BuffRate={Odds=100},BuffEffect={Itemid=62567,SkillID=1009002,type='GetSkill'},Dsc='湮灭者了解世间万物生存法则，能更好的保护使用者。湮灭者施放力量使使用者及8米范围内的同队队友获得【生存即湮灭】效果。【生存即湮灭】：免疫一切伤害和控制效果，持续5秒，CD：180秒',}",
  [47280] = "{id=47280,BuffName='硝烟终结者4[1]',BuffRate={Odds=100},BuffEffect={Agi=20,AngelDamPer=0.6,AtkPer=0.4,BruteDamPer=0.6,DamReduc=0.15,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=20,DragonDamPer=0.6,EquipASPD=0.1,FishDamPer=0.6,FormlessDamPer=0.6,IgnoreDef=0.35,InsectDamPer=0.6,Int=20,Luk=20,MDamReduc=0.15,MaxHp=40000,PlantDamPer=0.6,Str=35,Vit=35,type='AttrChange'},Dsc='力量＋15\n体质＋15\n全能力＋20\n装备攻速＋10%\n物理攻击＋40%\n忽视物理防御＋35%\n对全种族伤害＋60%\n生命上限＋40000\n物伤减免＋15%，魔伤减免＋15%',}",
  [47281] = "{id=47281,BuffName='硝烟终结者',BuffRate={Odds=100},BuffEffect={Itemid=41898,SkillID=1004002,type='GetSkill'},Dsc='硝烟终结者的力量影响着使用者。将使8米内所有友方目标都获得【势如破竹】效果。【势如破竹】:受到任何攻击都不会造成硬直，自身伤害＋50%，移动速度＋50%，持续5秒，CD：120秒',}",
  [47290] = "{id=47290,BuffName='凛冬结晶4[1]',BuffRate={Odds=100},BuffEffect={Agi=32,AngelDamPer=0.6,BruteDamPer=0.6,Cri=50,CriDamPer=0.5,DamReduc=0.15,DamSpike=0.08,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=38,DragonDamPer=0.6,FishDamPer=0.6,FormlessDamPer=0.6,InsectDamPer=0.6,Int=20,Luk=20,MDamReduc=0.15,MaxHp=37500,PlantDamPer=0.6,Str=20,Vit=20,type='AttrChange'},Dsc='灵巧＋18\n敏捷＋12\n全能力＋20\n暴击＋50\n暴击伤害＋50%\n物理穿刺＋8%\n对全种族伤害＋60%\n生命上限＋37500\n物伤减免＋15%，魔伤减免＋15%',}",
  [47291] = "{id=47291,BuffName='凛冬结晶',BuffRate={Odds=100},BuffEffect={Itemid=41286,SkillID=1002002,type='GetSkill'},Dsc='被凛冬结晶攻击的目标将受到冰霜结晶的额外伤害。每次普通攻击冰霜结晶将对被攻击者额外造成自身攻击*（1.5＋暴伤）*50%的真实伤害，并对该目标周围4米内最多6名敌对目标造成攻击*（1.5＋暴伤）*25%的真实伤害。受到冰霜结晶影响的目标有5%的概率被冰冻，冰冻时间持续2秒。',}",
  [47300] = "{id=47300,BuffName='神器书4',BuffRate={Odds=100},BuffEffect={Agi=25,AngelDamPer=0.6,AtkPer=0.2,BruteDamPer=0.6,DamIncrease=0.05,DamReduc=0.15,DamSpike=0.25,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=20,DragonDamPer=0.6,FishDamPer=0.6,FormlessDamPer=0.6,InsectDamPer=0.6,Int=35,Luk=20,MAtkPer=0.2,MDamReduc=0.15,MDamSpike=0.25,MaxHp=37500,PlantDamPer=0.6,RangeDam=0.15,Str=35,Vit=30,type='AttrChange'},Dsc='智力＋15、力量＋15\n敏捷＋5\n体质＋10\n全能力＋20\n提升贤者系范围型技能伤害＋15%，物理伤害＋5%\n物理、魔法攻击＋20%\n物理、魔法穿刺＋25%\n对全种族伤害＋60%\n生命上限＋37500\n物伤减免＋15%，魔伤减免＋15%',}",
  [47301] = "{id=47301,BuffName='风暴之心',BuffRate={Odds=100},BuffEffect={Itemid=63483,SkillID=1025002,type='GetSkill'},Dsc='获得技能【风暴之心】：在施法者周围形成半径6米的风暴，在风暴中的所有敌对目标每秒将受到300%的风属性和300%的水属性魔法伤害，移动速度下降75%，攻击速度下降75%，物理和魔法攻击下降40%。风暴可跟随施法者一起移动。风暴可以击中隐匿的敌对目标并使其出现。施法者在使用风暴之心技能时，物理、魔法穿刺＋30%，受到的所有伤害降低50%。风暴持续 12 秒，技能冷却时间 120 秒',}",
  [47310] = "{id=47310,BuffName='神器乐器4',BuffRate={Odds=100},BuffEffect={Agi=40,AngelDamPer=0.6,AtkPer=0.18,BruteDamPer=0.6,DamReduc=0.15,DamSpike=0.15,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=52,DragonDamPer=0.6,FishDamPer=0.6,FormlessDamPer=0.6,InsectDamPer=0.6,Int=48,Luk=40,MDamReduc=0.15,MaxHp=50000,MaxHpPer=0.1,PlantDamPer=0.6,Str=40,Vit=50,type='AttrChange'},Dsc='灵巧＋12\n智力＋8\n体质＋10\n全能力＋40\n生命上限＋10%\n物理攻击＋18%\n物理穿刺＋15%\n对全种族伤害＋60%\n生命上限＋50000\n物伤减免＋15%，魔伤减免＋15%',}",
  [47311] = "{id=47311,BuffName='守护天使',BuffRate={Odds=100},BuffEffect={Itemid=63162,SkillID=1023002,type='GetSkill'},Dsc='可对队伍中的所有目标施放【守护天使】。【守护天使】：使目标受到的伤害降低30%，攻击速度＋30%，移动速度和攻击速度不会受到任何效果降低（包括神器技能），当目标死亡时守护天使将使目标避免死亡并为其回复80%MaxHp和50%MaxSp，【守护天使】效果不会被任何技能解除。【守护天使】持续8秒，冷却时间150s',}",
  [47320] = "{id=47320,BuffName='神器鞭子4',BuffRate={Odds=100},BuffEffect={Agi=40,AngelDamPer=0.6,AtkPer=0.18,BruteDamPer=0.6,DamReduc=0.15,DamSpike=0.15,DeadLessDamPer=0.6,DemiHumanDamPer=0.6,DemonDamPer=0.6,Dex=52,DragonDamPer=0.6,FishDamPer=0.6,FormlessDamPer=0.6,InsectDamPer=0.6,Int=48,Luk=40,MDamReduc=0.15,MaxHp=50000,MaxHpPer=0.1,PlantDamPer=0.6,Str=40,Vit=50,type='AttrChange'},Dsc='灵巧＋12\n智力＋8\n体质＋10\n全能力＋40\n生命上限＋10%\n物理攻击＋18%\n物理穿刺＋15%\n对全种族伤害＋60%\n生命上限＋50000\n物伤减免＋15%，魔伤减免＋15%',}",
  [47321] = "{id=47321,BuffName='恐惧炸弹',BuffRate={Odds=100},BuffEffect={Itemid=62860,SkillID=1024002,type='GetSkill'},Dsc='可对范围内的5个敌对目标施放【恐惧炸弹】。【恐惧炸弹】：目标因恐惧而四处乱跑，目标在恐惧炸弹效果结束后若仍存活，将对周围3米的所有友方目标施放【深层恐惧】，持续3s，冷却时间75s。【深层恐惧】：目标将被恐惧而四处乱跑，移动速度＋30%，受到伤害＋30%，持续 5 秒',}",
